function* range(start, end) {
  let current = start;
  while (current < end) {
    yield current;
    current += 1;
  }
  return current;
}

const values = range(2, 4);
console.log(values.next()); // { value: 2, done: false }
console.log(values.next()); // { value: 3, done: false }
console.log(values.next()); // { value: 4, done: true }

const alphabet = {
  *[Symbol.iterator]() {
    yield 'a';
    yield 'b';
  }
};

console.log([...alphabet]); // ['a', 'b']
console.log([...alphabet]); // ['a', 'b'] — каждый раз создаётся новый генератор

const oneShot = alphabet[Symbol.iterator]();
console.log([...oneShot]); // ['a', 'b']
console.log([...oneShot]); // [] — iterator исчерпан

function* readRows() {
  try {
    yield 'row 1';
    yield 'row 2';
  } finally {
    console.log('освободить ресурсы iterator');
  }
}

for (const row of readRows()) {
  console.log(row);
  break;
}

